package vmcompat;
import java.lang.instrument.*;import java.nio.file.*;import java.lang.classfile.*;import java.lang.classfile.instruction.*;import java.util.*;
/** Test-only final observer, registered after ZombieBuddy. Does not run the game. */
public final class CompositionInspect {
 static final List<String> NAMES=List.of("zombie/core/opengl/RenderThread","zombie/core/SpriteRenderer","viewpoint/FP","viewpoint/SceneDrawer","viewpoint/Hooks","viewpoint/platform/FrameTimes","viewpoint/platform/VideoMemory","viewpoint/platform/MemoryCensus","viewpoint/platform/Onboarding","viewpoint/render/FarPass","viewpoint/render/ShellArena","viewpoint/render/ShellArena$Page");
 static Instrumentation instrumentation;
 public static void premain(String args,Instrumentation inst){instrumentation=inst;inst.addTransformer(new ClassFileTransformer(){public byte[] transform(ClassLoader loader,String name,Class<?> old,java.security.ProtectionDomain pd,byte[] bytes){if(NAMES.contains(name)){try{Path p=Path.of(System.getProperty("vmcompat.finalDump"),name+".class");Files.createDirectories(p.getParent());Files.write(p,bytes);}catch(Exception e){throw new RuntimeException(e);}}return null;}},true);}
 public static void main(String[] args)throws Exception{for(String name:NAMES.stream().map(x->x.replace('/','.')).toList())Class.forName(name,false,CompositionInspect.class.getClassLoader());for(String name:NAMES.stream().map(x->x.replace('/','.')).toList())instrumentation.retransformClasses(Class.forName(name,false,CompositionInspect.class.getClassLoader()));Path root=Path.of(System.getProperty("vmcompat.finalDump"));for(String name:NAMES){byte[] b=Files.readAllBytes(root.resolve(name+".class"));var model=ClassFile.of().parse(b);if(!ClassFile.of().verify(b).isEmpty())throw new AssertionError(name+" verifier");List<String> calls=new ArrayList<>();for(var m:model.methods())if(m.code().isPresent())for(var c:m.code().get())if(c instanceof InvokeInstruction i)calls.add(m.methodName().stringValue()+" -> "+i.owner().asInternalName()+"."+i.name().stringValue());Files.writeString(root.resolve(name.replace('/','_')+"-calls.txt"),String.join("\n",calls));if(name.equals("viewpoint/FP")&&!calls.contains("renderWorld -> vmcompat/Breakdown.drawerQueued"))throw new AssertionError("missing queue publication hook");if(name.equals("viewpoint/SceneDrawer")&&calls.stream().anyMatch(x->x.contains("drawerReleased")))throw new AssertionError("pooled mapping removed");
 if(name.equals("zombie/core/SpriteRenderer")){var post=calls.stream().filter(x->x.startsWith("postRender ->")).toList();int start=post.indexOf("postRender -> viewpoint/Hooks.gameRenderStarted"),open=post.indexOf("postRender -> vmcompat/Breakdown.open"),close=post.indexOf("postRender -> vmcompat/Breakdown.close"),end=post.indexOf("postRender -> viewpoint/Hooks.gameRenderEnded");if(!(start>=0&&start<open&&close<end))throw new AssertionError("final postRender external advice boundaries");}
 if(name.equals("viewpoint/render/ShellArena")){if(calls.contains("issue -> vmcompat/Draws.glMultiDrawElementsIndirect")){if(Options.FAR_BATCH)throw new AssertionError("unqualified indexed fast batch");}else if(!calls.contains("issue -> vmcompat/FarShell.begin")||!calls.contains("issue -> vmcompat/FarShell.draw")||!calls.contains("free -> vmcompat/FarShell.free")||!calls.contains("letGo -> vmcompat/FarShell.remove"))throw new AssertionError("missing far typed bridge");}if(name.equals("viewpoint/render/FarPass")&&!calls.contains("uploadMask -> vmcompat/FarMasks.upload"))throw new AssertionError("mask bridge missing");
 if(name.startsWith("viewpoint/platform/")||name.equals("viewpoint/Hooks")){if(calls.stream().noneMatch(x->x.endsWith("vmcompat/Breakdown.open")))throw new AssertionError("missing narrow timer "+name);}
 if(name.equals("viewpoint/platform/FrameTimes")&&!calls.contains("renderStarted -> vmcompat/FrameTimesGpu.begin"))throw new AssertionError("missing GPU guard bridge");
 }System.out.println("FINAL COMPOSITION VERIFIED");}
}
